def is_arithmetic(seq):
    if len(seq) < 2:
        return True
    diff = seq[1] - seq[0]
    return all(seq[i] - seq[i-1] == diff for i in range(2, len(seq)))

def find_split(n, a):
    a.sort()
    for i in range(1, n):
        for j in range(i+1, n):
            seq1 = a[:i]
            seq2 = a[i:j]
            seq3 = a[j:]
            if is_arithmetic(seq1) and is_arithmetic(seq2) and is_arithmetic(seq3):
                return [seq1, seq2 + seq3]
    return None

